//
// Thus, the task is to count all contiguous subarrays whose removal leaves a strictly increasing sequence, including the entire array (leaving empty) if the remaining empty array is considered increasing. Typically, in the official problem, an empty array is considered strictly increasing. So we follow that.
//
// Now, to create a standalone task, we need to describe the problem clearly and provide a reference solution. The solution should be efficient (O(n) time, O(1) space). Edge cases: entire array already increasing -> return n*(n+1)/2. Single element array: n=1, then it's increasing, return 1. Also consider arrays with duplicates.
//
// We'll write a function `long long countIncremovableSubarrays(const vector<int>& nums)`.

#include <vector>

// Counts contiguous subarrays whose removal leaves a strictly increasing sequence.
// Empty remaining sequence is considered strictly increasing.
long long countIncremovableSubarrays(const std::vector<int>& nums) {
    const long long n = static_cast<long long>(nums.size());

    // Find the longest strictly increasing prefix: indices [0, leftIdx].
    long long leftIdx = 0;
    while (leftIdx + 1 < n && nums[leftIdx] < nums[leftIdx + 1]) {
        ++leftIdx;
    }

    // If the entire array is already strictly increasing, every subarray works.
    if (leftIdx == n - 1) {
        return n * (n + 1) / 2;
    }

    // Find the longest strictly increasing suffix: indices [rightIdx, n-1].
    long long rightIdx = n - 1;
    while (rightIdx - 1 >= 0 && nums[rightIdx - 1] < nums[rightIdx]) {
        --rightIdx;
    }

    // Base: removals that start at index 0 (no kept prefix).
    // Valid end indices are from rightIdx-1 to n-1, giving (n - rightIdx + 1) choices.
    long long result = n - rightIdx + 1;

    // Two-pointer sweep: l is the last index of the kept prefix,
    // so the removed subarray starts at l+1. r is the first index after the wanted end.
    long long r = rightIdx;
    for (long long l = 0; l <= leftIdx; ++l) {
        // Advance r until the kept suffix (starting at r) is compatible with the kept prefix.
        while (r < n && nums[l] >= nums[r]) {
            ++r;
        }
        // For this l, all ends from r-1 to n-1 are valid.
        result += n - r + 1;
    }

    return result;
}

